//! Checks repository file naming conventions.

use std::{fmt, path::Path};

pub use conceptory_diagnostic::Diagnostic;
use globset::{Glob, GlobSet, GlobSetBuilder};
use ignore::WalkBuilder;

/// Files excluded from the check by default.
///
/// These are all generated by tools that choose their names, so their extensions cannot be
/// changed.
pub const DEFAULT_EXCLUDES: &[&str] = &[
    // Snapshots generated by ast-grep's `sg test`. A rule ID containing `/` places them in a
    // subdirectory of `__snapshots__`
    "**/__snapshots__/**/*-snapshot.yml",
];

/// A failure to walk the files or to parse an exclude pattern.
#[derive(Debug)]
pub enum Error {
    /// The directory could not be walked.
    Walk(ignore::Error),
    /// An exclude pattern could not be parsed.
    Glob(globset::Error),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Walk(error) => write!(f, "ファイルを走査できません: {error}"),
            Self::Glob(error) => write!(f, "除外するパターンを解釈できません: {error}"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Walk(error) => Some(error),
            Self::Glob(error) => Some(error),
        }
    }
}

/// Checks the names of the files under `root`.
///
/// Skips files ignored by `.gitignore` and files matching a pattern in [`DEFAULT_EXCLUDES`] or
/// `excludes`. Patterns are matched against paths relative to `root`.
///
/// # Errors
///
/// Returns [`Error::Walk`] if the directory cannot be walked, or [`Error::Glob`] if a pattern
/// cannot be parsed.
pub fn check(root: &Path, excludes: &[String]) -> Result<Vec<Diagnostic>, Error> {
    let excludes = build_excludes(excludes)?;
    let walker = WalkBuilder::new(root)
        .hidden(false)
        .require_git(false)
        .filter_entry(|entry| entry.file_name() != ".git")
        .build();

    let mut diagnostics = Vec::new();
    for entry in walker {
        let entry = entry.map_err(Error::Walk)?;
        if !entry.file_type().is_some_and(|kind| kind.is_file()) {
            continue;
        }
        let path = entry.path();
        let rel = path.strip_prefix(root).unwrap_or(path);
        if excludes.is_match(rel) {
            continue;
        }
        if path
            .extension()
            .is_some_and(|extension| extension.eq_ignore_ascii_case("yml"))
        {
            let display = if root == Path::new(".") { rel } else { path };
            diagnostics.push(Diagnostic::new(
                display.display().to_string(),
                1,
                "yaml-extension",
                "YAML ファイルの拡張子は `.yaml` にしてください",
            ));
        }
    }
    diagnostics.sort();
    Ok(diagnostics)
}

/// Combines the patterns in [`DEFAULT_EXCLUDES`] and `excludes`.
///
/// # Errors
///
/// Returns [`Error::Glob`] if a pattern cannot be parsed.
fn build_excludes(excludes: &[String]) -> Result<GlobSet, Error> {
    let mut builder = GlobSetBuilder::new();
    for pattern in DEFAULT_EXCLUDES
        .iter()
        .copied()
        .chain(excludes.iter().map(String::as_str))
    {
        builder.add(Glob::new(pattern).map_err(Error::Glob)?);
    }
    builder.build().map_err(Error::Glob)
}
